<?php
/**
 * Unit tests run against the Magento packages in vendor/ (composer install), without a Magento installation.
 */
declare(strict_types=1);

use Magento\Framework\Code\Generator\Io;
use Magento\Framework\Filesystem\Driver\File;
use Magento\Framework\TestFramework\Unit\Autoloader\FactoryGenerator;
use Magento\Framework\TestFramework\Unit\Autoloader\GeneratedClassesAutoloader;

require __DIR__ . '/../../vendor/autoload.php';
require_once __DIR__ . '/../../vendor/magento/framework/Phrase/__.php';

// *Factory classes are generated by Magento at runtime; generate them on demand like Magento's own unit tests do.
$io = new Io(new File(), sys_get_temp_dir() . '/payfurl-magento-unit-generated');
spl_autoload_register([new GeneratedClassesAutoloader([new FactoryGenerator()], $io), 'load']);
